    # Find the full divider between the two panels.
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            n = min(len(left[0]), len(right[0]))

            # Each panel's dominant color is its background. Mark positions
            # that are foreground in both panels.
            from collections import Counter
            lb = Counter(x for row in left for x in row).most_common(1)[0][0]
            rb = Counter(x for row in right for x in row).most_common(1)[0][0]
            out = [[lb] * n for _ in range(h)]
            for r in range(h):
                for k in range(n):
                    if left[r][k] != lb and right[r][k] != rb:
                        out[r][k] = 3
            return out

    return grid
